using System;using System.Linq;using System.Drawing;using System.Collections.Generic;
namespace GearLab {
 public sealed partial class CadBuilder {
  CadAssembly model=new CadAssembly();Parameters p;Result r;int serial;Color steel=Color.FromArgb(155,169,184),housing=Color.FromArgb(105,135,158),fixedColor=Color.FromArgb(51,136,116),blue=Color.FromArgb(47,139,199),orange=Color.FromArgb(221,148,58);
  CadBuilder(Result result){r=result;p=result.P;}
  CadPart Part(string code,string label,string role,Color color){var part=new CadPart((++serial).ToString("000")+"_"+code,label,role,color);model.Parts.Add(part);return part;}
  CadPart Extrude(string code,string label,string role,Color color,CadLoop outer,double z,double height,params CadLoop[] holes){if(height<1e-6)throw new Exception("Толщина детали "+label+" должна быть положительной.");var part=Part(code,label,role,color);part.Sections.Add(new CadSection(z,z+height,outer,holes));return part;}
  CadLoop C(double x,double y,double radius){return CadLoop.Round(x,y,radius);}
  CadPart Tube(string code,string label,string role,Color color,double x,double y,double od,double id,double z,double height){return Extrude(code,label,role,color,C(x,y,od/2),z,height,id>0?new[]{C(x,y,id/2)}:new CadLoop[0]);}
  PointF[] Hex(double x,double y,double flat){double radius=flat/Math.Sqrt(3);return Enumerable.Range(0,6).Select(i=>Engine.Polar(radius,Engine.Tau*i/6)).Select(v=>new PointF((float)(v.X+x),(float)(v.Y+y))).ToArray();}
  CadLoop Rectangle(double x0,double y0,double x1,double y1){return CadLoop.Polygon(new[]{new PointF((float)x0,(float)y0),new PointF((float)x1,(float)y0),new PointF((float)x1,(float)y1),new PointF((float)x0,(float)y1)});}
  List<PointF> Positions(int count,double radius,double angle){return Enumerable.Range(0,count).Select(i=>Engine.Polar(radius,Engine.Tau*i/count+angle)).ToList();}
  List<PointF> MotorPositions(){var a=new List<PointF>();if(p.MotorFrame>0&&p.MotorMount>0&&p.MotorHole>0)for(int i=-1;i<=1;i+=2)for(int j=-1;j<=1;j+=2)a.Add(new PointF((float)(i*p.MotorMount/2),(float)(j*p.MotorMount/2)));return a;}
  CadLoop[] At(IEnumerable<PointF> pos,double diameter){return pos.Select(v=>C(v.X,v.Y,diameter/2)).ToArray();}
  void Bearing(string code,string label,double x,double y,double inner,double outer,double z,double width){var part=Tube(code,label,"bearing",steel,x,y,outer,inner,z,width);part.Note="Габаритная модель подшипника d="+Engine.F(inner)+", D="+Engine.F(outer)+", B="+Engine.F(width)+" мм. Марка, дорожки, зазоры и внутреннее устройство не выбраны.";}
  void Bolt(string code,string label,double x,double y,double z,double length,double diameter,bool socket){double head=diameter*.7,af=diameter*1.833333;var part=Part(code,label,"fastener",steel);part.Sections.Add(new CadSection(z-head,z,socket?C(x,y,diameter*.92):CadLoop.Polygon(Hex(x,y,af)),null));part.Sections.Add(new CadSection(z,z+length,C(x,y,diameter/2),null));part.Note="Упрощённый крепёж: гладкий стержень вместо резьбы; длина и тип головки — параметры компоновки.";}
  void Nut(string code,double x,double y,double z,double diameter){Extrude(code,"Гайка Ø"+Engine.F(diameter),"fastener",steel,CadLoop.Polygon(Hex(x,y,diameter*1.833333)),z,diameter*.8,C(x,y,diameter/2));}
  void ReverseBolt(string code,string label,double x,double y,double z,double length,double diameter,double headFactor=.7){var part=Part(code,label,"fastener",steel);part.Sections.Add(new CadSection(z-length,z,C(x,y,diameter/2),null));part.Sections.Add(new CadSection(z,z+diameter*headFactor,C(x,y,diameter*.92),null));part.Note="Упрощённый винт без резьбы, головка со стороны +Z.";}
  void BackPlate(string code,CadLoop outer,double height,List<CadLoop> holes){double diameter=p.MotorHole>=4.5?5:p.ModelBolt,split=height-diameter*.7;if(split<=0)throw new Exception("Крышка слишком тонкая для головок моторных винтов.");var mounting=MotorPositions();var part=Part(code,"Моторная крышка с цековками","housing",housing);var levels=new[]{0.0,Math.Min(2,height),split,height}.Distinct().OrderBy(v=>v).ToArray();for(int j=0;j<levels.Length-1;j++){var current=holes.ToList();if(levels[j]>=split-1e-7)foreach(var v in mounting){int index=current.FindIndex(h=>h.Circle&&Math.Abs(h.X-v.X)<1e-6&&Math.Abs(h.Y-v.Y)<1e-6);if(index>=0)current[index]=C(v.X,v.Y,diameter*.92+Fit);}if(levels[j]<2&&p.MotorFrame>0){int index=current.FindIndex(h=>h.Circle&&Math.Abs(h.X)<1e-6&&Math.Abs(h.Y)<1e-6);if(index>=0)current[index]=C(0,0,Math.Max(current[index].R,(p.MotorPilot+2*Fit)/2));}part.Sections.Add(new CadSection(levels[j],levels[j+1],outer,current));}foreach(var v in mounting)ReverseBolt("MOTOR_SCREW","Винт крепления мотора",v.X,v.Y,split,split+5,diameter);}
  void Motor(){if(p.MotorFrame<=0||p.MotorLength<=0)return;var part=Part("MOTOR_REFERENCE","Мотор: габарит и монтажный интерфейс","reference",Color.FromArgb(77,88,103));part.Reference=true;var holes=new List<CadLoop>{C(0,0,(p.Shaft+2*p.ModelGap)/2)};holes.AddRange(At(MotorPositions(),p.MotorHole>=4.5?5:p.ModelBolt));part.Sections.Add(new CadSection(-p.MotorLength,0,Rectangle(-p.MotorFrame/2,-p.MotorFrame/2,p.MotorFrame/2,p.MotorFrame/2),holes));if(p.MotorPilot>p.Shaft+2*p.ModelGap)part.Sections.Add(new CadSection(0,2,C(0,0,p.MotorPilot/2),new[]{holes[0]}));part.Note="Габаритный образец мотора, не модель его внутренних деталей. Бурт принят высотой 2 мм, винты М3/М5 по отверстию; длину/форму вала и крепёж сверить с паспортом.";}
  double Fit {get{return Math.Max(.05,p.Clearance);}}
  void Cycle(){
   double g=p.ModelGap,cover=p.ModelCover,layer=Math.Max(p.Thickness,p.BearingSimulation?p.BearingWidth:p.Thickness),bearingB=p.BearingSimulation?p.BearingWidth:Math.Min(layer,7),bearingd=p.BearingSimulation?p.BearingInner:p.Shaft+2*p.Eccentric+1;
   double coreOuter=p.Radius+p.Roller/2+p.Wall,outer=coreOuter+p.ModelFlange,innerWall=p.Radius+p.Roller/2+p.Clearance;
   var pins=Positions(p.OutputPins,p.OutputRadius,0);var rollers=Positions(r.Pins,p.Radius,0);double pinOuter=p.OutputRadius+p.OutputPin/2;
