   if(caseInner<=2*pinOuter||caseOuter<=caseInner||caseOuter/2+3>=outer)throw new Exception("Опоры корпуса не помещаются: нужны d > "+Engine.F(2*pinOuter)+" и D < "+Engine.F(2*(outer-3))+" мм. Измените монтажный пояс или размеры опор 3D.");
   if(!p.IntegratedRing&&p.ModelRollerAxle>=p.Roller)throw new Exception("Ось ролика должна быть меньше наружного Ø ролика.");if(p.ModelBolt+2*Fit>=p.OutputPin)throw new Exception("Для полых пальцев нужен Ø пальца больше Ø стяжки + зазор. Уменьшите крепёж 3D или увеличьте пальцы.");
   double mountingRadius=(Math.Max(innerWall,caseOuter/2)+outer)/2;if(outer-mountingRadius<p.ModelBolt/2+Fit+.5)throw new Exception("Монтажный пояс слишком узкий для болтов корпуса.");var bolts=Positions(p.ModelBoltCount,mountingRadius,Math.PI/p.ModelBoltCount);
   double hubTop=cover+g+2*caseB+g,carrierStart=hubTop,workBase=carrierStart+cover,workStart=workBase+g,packet=p.Discs*layer+(p.Discs-1)*p.DiscGap,wallTop=workStart+packet+g,capTop=wallTop+cover,frontStart=capTop+g,frontThickness=cover+p.ModelInputBearingB,frontTop=frontStart+frontThickness;
   double fixedRadius=Math.Max(caseInner/2+2,p.MotorFrame>0?Math.Sqrt(2)*(p.MotorMount+p.MotorHole)/2+2:0),frontRadius=pinOuter+3;
   var mounting=MotorPositions();var baseHoles=new List<CadLoop>{C(0,0,p.MotorPilot>0?(p.MotorPilot+2*Fit)/2:p.ModelInputBearingD/2)};baseHoles.AddRange(At(pins,p.ModelBolt*2.12+2*Fit));baseHoles.AddRange(At(mounting,Math.Max(p.MotorHole,p.ModelBolt+2*Fit)));
   double motorBolt=p.MotorHole>=4.5?5:p.ModelBolt;if(cover<p.ModelBolt*.7+motorBolt*.55)throw new Exception("Моторная плита слишком тонкая для головок: задайте крышку 3D не менее "+Engine.F(p.ModelBolt*.7+motorBolt*.55)+" мм.");var topHoles=new List<CadLoop>{C(0,0,p.ModelInputBearingD/2)};topHoles.AddRange(At(pins,p.OutputPin));topHoles.AddRange(At(mounting,motorBolt*1.84+2*Fit));
   var baseplate=Part("FIXED_MOTOR_PLATE","Неподвижная моторная плита","fixed",fixedColor);double pocket=Math.Min(p.ModelBolt*.7,cover*.75);baseplate.Sections.Add(new CadSection(0,pocket,C(0,0,fixedRadius),baseHoles));baseplate.Sections.Add(new CadSection(pocket,cover,C(0,0,fixedRadius),topHoles));
   var hubHoles=new List<CadLoop>{C(0,0,p.ModelInputBearingD/2)};hubHoles.AddRange(At(pins,p.OutputPin));Extrude("FIXED_HUB","Неподвижная ступица опор корпуса","fixed",fixedColor,C(0,0,caseInner/2),cover,hubTop-cover,hubHoles.ToArray());
   Bearing("INPUT_REAR_BEARING","Задняя опора входного вала",0,0,p.Shaft,p.ModelInputBearingD,cover,p.ModelInputBearingB);
   for(int j=0;j<2;j++)Bearing("CASE_BEARING_"+(j+1),"Опора вращающегося корпуса "+(j+1),0,0,caseInner,caseOuter,cover+g+j*(caseB+g),caseB);
   var rearHoles=new List<CadLoop>{C(0,0,caseOuter/2)};rearHoles.AddRange(At(bolts,p.ModelBolt+2*Fit));Extrude("CASE_BEARING_CARRIER","Обойма опор корпуса","housing",housing,C(0,0,outer),cover+g,hubTop-cover-g,rearHoles.ToArray());
   double opening=Math.Max(pinOuter+g,caseInner/2+g);var mountHoles=new List<CadLoop>{C(0,0,opening)};mountHoles.AddRange(At(rollers,p.ModelRollerAxle));mountHoles.AddRange(At(bolts,p.ModelBolt+2*Fit));Extrude("ROLLER_REAR_COVER","Задняя крышка и опора осей роликов","housing",housing,C(0,0,outer),carrierStart,cover,mountHoles.ToArray());
   var wallHoles=new List<CadLoop>{C(0,0,innerWall)};wallHoles.AddRange(At(bolts,p.ModelBolt+2*Fit));Extrude("CASE_WALL","Наружная стенка корпуса","housing",housing,C(0,0,outer),workBase,wallTop-workBase,wallHoles.ToArray());Extrude("ROLLER_FRONT_COVER","Передняя крышка и опора осей роликов","housing",housing,C(0,0,outer),wallTop,cover,mountHoles.ToArray());
