    double angle=j==0?0:-Math.PI/r.Lobes;var profile=CadLoop.Polygon(Engine.Transform(r.Profile,x,0,angle));var discHoles=new List<CadLoop>{C(x,0,p.Bore/2)};discHoles.AddRange(pins.Select(v=>C(v.X+x,v.Y,r.Hole/2)));Extrude("CYCLOID_DISC_"+(j==0?"A":"B"),"Циклоидальный диск "+(j==0?"A":"B"),"gear",j==0?blue:orange,profile,discZ,p.Thickness,discHoles.ToArray());Bearing("ECCENTRIC_BEARING_"+(j+1),"Подшипник диска "+(j+1),x,0,bearingd,p.Bore,bearingZ,bearingB);
   }
   shaft.Sections.Add(new CadSection(last,frontTop+2+p.ModelShaftExtension,C(0,0,p.Shaft/2),null));
   var retention=Positions(3,11.5,Math.PI/3);var frontHoles=new List<CadLoop>{C(0,0,p.ModelInputBearingD/2)};frontHoles.AddRange(At(pins,p.OutputPin));frontHoles.AddRange(At(retention,p.ModelBolt+2*Fit));Extrude("FIXED_FRONT_CARRIER","Передний неподвижный фланец пальцев","fixed",fixedColor,C(0,0,frontRadius),frontStart,frontThickness,frontHoles.ToArray());Bearing("INPUT_FRONT_BEARING","Передняя опора входного вала",0,0,p.Shaft,p.ModelInputBearingD,frontStart+cover,p.ModelInputBearingB);
   var retainerHoles=new List<CadLoop>{C(0,0,(p.Shaft+(p.ModelInputBearingD-p.Shaft)*.65)/2)};retainerHoles.AddRange(At(retention,p.ModelBolt+2*Fit));Extrude("INPUT_BEARING_RETAINER","Прижим передней опоры вала","fixed",fixedColor,C(0,0,15),frontTop,1.5,retainerHoles.ToArray());foreach(var v in retention)ReverseBolt("RETAINER_SCREW","Винт прижима опоры",v.X,v.Y,frontTop+1.5,cover+1.5,p.ModelBolt);
