  void StandardCycle(){
   double g=p.ModelGap,cover=p.ModelCover,layer=Math.Max(p.Thickness,p.BearingSimulation?p.BearingWidth:p.Thickness),bb=p.BearingSimulation?p.BearingWidth:Math.Min(layer,7),bd=p.BearingSimulation?p.BearingInner:p.Shaft+2*p.Eccentric+1,outer=p.Radius+p.Roller/2+p.Wall+p.ModelFlange,wallInner=p.Radius+p.Roller/2+p.Clearance;
   double od=p.ModelCaseOuter>0?p.ModelCaseOuter:p.OutputShaft+14,ob=p.ModelCaseBearingB;if(p.ModelCaseInner>0&&Math.Abs(p.ModelCaseInner-p.OutputShaft)>1e-6)throw new Exception("Ø выходной опоры должен совпадать с выходным валом.");if(!p.IntegratedRing&&p.ModelRollerAxle>=p.Roller)throw new Exception("Ось ролика должна быть меньше ролика.");
