   var holes=new List<CadLoop>{C(0,0,p.ModelInputBearingD/2)};holes.AddRange(At(rollers,p.ModelRollerAxle));holes.AddRange(At(bolts,p.ModelBolt+2*Fit));holes.AddRange(At(MotorPositions(),Math.Max(p.MotorHole,p.ModelBolt+2*Fit)));BackPlate("FIXED_CASE_BACK",C(0,0,outer),backT,holes);
