   var wallHoles=new List<CadLoop>{C(0,0,wallInner)};wallHoles.AddRange(At(bolts,p.ModelBolt+2*Fit));Extrude("FIXED_CASE_WALL","Неподвижная стенка кольца","housing",housing,C(0,0,outer),backT,frontZ-backT,wallHoles.ToArray());var frontHoles=new List<CadLoop>{C(0,0,od/2)};frontHoles.AddRange(At(rollers,p.ModelRollerAxle));frontHoles.AddRange(At(bolts,p.ModelBolt+2*Fit));Extrude("FIXED_CASE_FRONT","Передняя крышка с опорами выхода","housing",housing,C(0,0,outer),frontZ,frontT,frontHoles.ToArray());for(int j=0;j<2;j++)Bearing("OUTPUT_BEARING_"+(j+1),"Опора выходного фланца",0,0,p.OutputShaft,od,frontZ+j*(ob+g),ob);
