   double carrierRadius=p.OutputRadius+p.OutputPin/2+3;if(carrierRadius>=wallInner-g)throw new Exception("Выходной фланец не помещается внутри корпуса. Измените радиус/Ø пальцев.");var output=Part("OUTPUT_CARRIER_SHAFT","Выходной фланец с валом","shaft",fixedColor);output.Sections.Add(new CadSection(carrierStart,carrierEnd,C(0,0,carrierRadius),At(pins,p.OutputPin)));output.Sections.Add(new CadSection(carrierEnd,frontEnd+p.ModelShaftExtension,C(0,0,p.OutputShaft/2),null));foreach(var v in pins)Tube("OUTPUT_PIN","Выходной палец","pin",steel,v.X,v.Y,p.OutputPin,0,start,carrierEnd-start);
