  void CommonBox(){
   double g=p.ModelGap,cover=p.ModelCover,c=p.Kind==1?r.Spacing:p.Center,driveRadius=p.Kind==1?p.Module*(r.Z1+2)/2:p.Pitch*r.Z1/(2*Math.PI),drivenRadius=p.Kind==1?p.Module*(r.Z2+2)/2:p.Pitch*r.Z2/(2*Math.PI);
   double margin=p.Wall+p.ModelFlange,x0=-Math.Max(driveRadius,p.MotorFrame/2)-margin,x1=c+drivenRadius+margin,half=Math.Max(drivenRadius,Math.Max(driveRadius,p.MotorFrame/2))+margin;
