  void Validate(){foreach(var part in model.Parts){if(part.Sections.Count==0||part.Volume()<=1e-6)model.Errors.Add("Нулевой объём: "+part.Label);foreach(var s in part.Sections){if(s.Top<=s.Bottom)model.Errors.Add("Нулевая толщина: "+part.Label);foreach(var h in s.Holes){var sample=h.Sample(24);if(sample.Any(v=>!s.Outer.Contains(v.X,v.Y)))model.Errors.Add("Отверстие выходит за контур: "+part.Label);}for(int i=0;i<s.Holes.Count;i++)for(int j=i+1;j<s.Holes.Count;j++){var a=s.Holes[i];var b=s.Holes[j];bool overlap=a.Circle&&b.Circle?Math.Sqrt((a.X-b.X)*(a.X-b.X)+(a.Y-b.Y)*(a.Y-b.Y))<a.R+b.R-1e-6:a.Sample(32).Any(v=>b.Contains(v.X,v.Y))||b.Sample(32).Any(v=>a.Contains(v.X,v.Y));if(overlap)model.Errors.Add("Отверстия/вырезы пересекаются: "+part.Label+". Уточните опоры, крепёж или монтажный пояс.");}}}}
  public static CadAssembly Build(Result result){var build=new CadBuilder(result);try{if(!result.Valid)throw new Exception("Сначала исправьте ошибки передачи.");if(build.p.ModelInputBearingD<=build.p.Shaft||build.p.ModelInputBearingB<=0||build.p.ModelCover<=0||build.p.ModelBolt<=0||build.p.ModelGap<.05||build.p.ModelFlange<2||build.p.ModelBoltCount<3||build.p.ModelBoltCount>16)throw new Exception("Проверьте параметры 3D: крышки, пояс, зазор, крепёж и входную опору.");build.Motor();if(build.p.Kind==0){if(build.p.CycloidLayout==1)build.MicroCycle();else if(build.p.RingOutput)build.Cycle();else build.StandardCycle();}else if(build.p.Kind==3)build.Planet();else build.CommonBox();IntegratedRing.Apply(build.model,result);build.Validate();build.model.Notes.Add("Круглые посадки и цилиндры экспортируются в STEP аналитически. Зубчатые профили остаются полилинейной аппроксимацией исходного расчёта. Резьбы, стопорные канавки, уплотнения, смазка, допуски и прочность требуют назначения.");build.model.Notes.Add("Мотор — габаритный образец; подшипники — габаритные кольца. Их внутренние детали не воспроизводятся. Геометрическая сборка не равнозначна проверенному производственному проекту.");}catch(Exception ex){build.model.Errors.Add(ex.Message);}return build.model;}
